function updateCompanySize(input){if(!Number.isFinite(input.sizeValue)||input.sizeValue<=0||!input.sizeLabel?.trim()||!safeURL(input.sizeSource)||!input.sizeScope?.trim()||!input.sizeAsOf?.trim())throw Error('请提供有效人数、显示区间、来源链接、统计口径与日期（未注明则如实填写）');const matches=jobs.filter(j=>companyKey(j.company)===companyKey(input.company));if(!matches.length)throw Error('没有匹配的公司记录');const info=sizeFields({...input,sizeChecked:datePlus(0)});if(!persist(jobs.map(j=>companyKey(j.company)===companyKey(input.company)?{...j,...info}:j)))throw Error('本地保存失败');render();return{ok:true,company:input.company,updated:matches.length,...info};}
