function metrics(){const actualJobs=jobs.filter(j=>j.kind!=='company');const counts=Object.fromEntries(statuses.map(s=>[s,actualJobs.filter(j=>j.status===s).length]));const total=actualJobs.length,pending=counts['计划投递'],submitted=counts['已投递'],written=counts['笔试'],interview=counts['面试中'],offer=counts.Offer,rejected=counts['未通过'],applied=total-pending,replied=interview+offer;return{total,pending,plannedCompanies:companyPlans().length,records:jobs.length,submitted,written,interview,ongoing:submitted+written+interview,offer,rejected,applied,replied,rate:applied?Math.round(replied/applied*1000)/10:0};}
function renderStats(){const m=metrics();if(window.OfferlyUI){window.OfferlyUI.renderStats($('#stats'),m);$('#backup-message').textContent=`已保存 ${m.records} 条记录，建议定期导出备份。`;$('#job-count').textContent=m.records;return;}$('#stats').innerHTML=[['岗位总计',m.total,'已明确的具体岗位','▦'],['计划投递',m.plannedCompanies,'家目标公司 · 先列清单','◷'],['进行中',m.ongoing,`已投 ${m.submitted} · 笔试 ${m.written} · 面试 ${m.interview}`,'↗'],['Offer',m.offer,'好消息，继续加油','♧'],['未通过',m.rejected,'复盘之后，再次出发','⊖'],['回复率',m.rate+'%','(面试 + Offer) / 总投递','↩']].map(([name,n,note,icon])=>`<div class="stat"><div class="stat-top">${name}<span class="stat-icon" aria-hidden="true">${icon}</span></div><div class="stat-number">${n}</div><div class="stat-note">${note}</div></div>`).join('');$('#backup-message').innerHTML=`数据已积累 <strong>${m.records}</strong> 条，建议导出备份。<span class="desktop-note"> 定期备份，让求职记录更安心。</span>`;$('#job-count').textContent=m.records;}
